<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $escape($job['title']) ?> · GigHub</title><link rel="stylesheet" href="assets/registration.css?v=4"><link rel="stylesheet" href="assets/jobs.css"></head><body><header class="site-header"><a class="brand" href="?route=/">GigHub</a><nav aria-label="Client navigation"><a href="?route=/client/jobs">My Jobs</a><a href="?route=/client/jobs/create">Post a Job</a></nav></header><main class="jobs-layout">
